"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["12162"],{25787(a){a.exports=JSON.parse('{"registro":{"codigo":"uniplus.selecao.etapa_processo.nota_minima_invalida","status":422,"titulo":"A nota m\xednima, quando informada, n\xe3o pode ser negativa"},"descricao":{"codigo":"uniplus.selecao.etapa_processo.nota_minima_invalida","requisitos":["UNI-REQ-0015"],"oQueAconteceu":["Uma das etapas do corpo do pedido informou `notaMinima` negativa. O campo \xe9 opcional\\n\u2014 uma etapa sem nota m\xednima n\xe3o elimina por nota nesta etapa \u2014, mas quando\\ninformado controla o corte de elimina\xe7\xe3o (etapas de car\xe1ter eliminat\xf3ria ou\\nambas): um valor negativo n\xe3o tem interpreta\xe7\xe3o v\xe1lida como corte de nota.","Esta \xe9 uma das confer\xeancias de forma que a defini\xe7\xe3o de etapas acumula numa s\xf3\\npassada, antes de resolver qualquer etapa contra o cat\xe1logo de tipos. A lista\\ncompleta das confer\xeancias, o mecanismo de acumula\xe7\xe3o e a ordem em que as viola\xe7\xf5es\\naparecem est\xe3o em [`nome_obrigatorio`](/erros/uniplus.selecao.etapa_processo.nome_obrigatorio).","O valor \xe9 persistido como `numeric(18,4)` \u2014 uma nota m\xednima com mais de 4\\ncasas decimais \xe9 recusada antes desta confer\xeancia, por valida\xe7\xe3o de corpo do pedido\\n(forma/rota, sem confer\xeancia de dom\xednio equivalente), para que o banco nunca\\narredonde silenciosamente o limiar de elimina\xe7\xe3o."],"comoResolver":["Informe uma `notaMinima` maior ou igual a zero, ou omita o campo se a etapa\\nn\xe3o deve eliminar por nota. Se a resposta trouxer mais de uma viola\xe7\xe3o no\\narray `errors[]`, corrija todas antes de reenviar."],"ondeAparece":["Defini\xe7\xe3o de etapas do processo seletivo"]},"modulo":{"id":"selecao","nome":"Sele\xe7\xe3o","assunto":"Etapa processo"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"fd5ea0ff72951399d2b2c1a4f29aeb3ea415db44"}}')}}]);